/**
 * Inferences (inf), rewritten to the Stellify question standard. Every passage reports a real, published study or
 * documented piece of scholarship, checked against its PubMed or Crossref record on the date in meta.source.
 * Where a passage poses a hypothetical (an orchard, a returning otter population), the general fact it rests on is
 * taken from the cited source and the scenario is stated as a hypothetical.
 */
import type { RawQuestion } from '@/lib/types';
import type { TrapCode } from '../distractors';

const CHECKED = '2026-11-27';
type Q = RawQuestion & { tags: (TrapCode | null)[] };
const STEM = 'Which choice most logically completes the text?';

interface Spec {
  id: string; d: RawQuestion['d']; sub: string; passage: string; choices: string[]; answer: number;
  tags: (TrapCode | null)[]; why: string[]; steps: string[]; cite: string; url: string; note: string;
}
function I(s: Spec): Q {
  return {
    id: s.id, skill: 'inf', sub: s.sub, d: s.d, passage: s.passage, stem: STEM, choices: s.choices, answer: s.answer,
    tags: s.tags, why: s.why, steps: s.steps,
    concept: 'A logical completion is the conclusion that the text’s own evidence supports: one careful step beyond it and no further.',
    strategy: 'Restate the evidence in your own words, predict the conclusion before reading the choices, then pick the choice that matches your prediction.',
    trap: 'A choice that overstates the evidence, reverses it, or brings in a claim the text never supports.',
    remember: 'The answer follows from the text, and it is usually the most cautious reasonable conclusion.',
    meta: {
      source: { cite: s.cite, url: s.url, checked: CHECKED },
      review: {
        teacher: `AI teacher pass (Stellify): ${s.note}`,
        bias: 'AI bias and clarity pass (Stellify): the passage supplies all needed context, no outside knowledge or cultural, regional or income assumptions are required, and the wording is plain with no double negatives.',
        date: CHECKED,
      },
    },
  };
}

